// FUNCTION: BFME2 0x0019B4E0 size=237 name=?Get_Bounding_Sphere@HLodClass@@UBEABVSphereClass@@XZ evidence=N:ledger tier=A
const SphereClass &HLodClass::Get_Bounding_Sphere(void) const
{
	if (BoundingBoxIndex >= 0) {
		//
		//	Get the bounding sphere in local coordinates
		//
		SphereClass sphere;
		Get_Obj_Space_Bounding_Sphere (sphere);

		//
		//	Transform the sphere into world coords and return the sphere
		//
		Get_Transform().mulVector3(sphere.Center, CachedBoundingSphere.Center);
		CachedBoundingSphere.Radius = sphere.Radius;
	} else if (!(Bits & BOUNDING_VOLUMES_VALID)) {
		Update_Cached_Bounding_Volumes();
	}

	return CachedBoundingSphere;
}

void HLodClass::Get_Obj_Space_Bounding_Sphere(SphereClass &sphere) const
{
	AABoxClass box;
	Get_Obj_Space_Bounding_Box(box);
	sphere.Center = box.Center;
	sphere.Radius = (float)sqrt(box.Extent.X * box.Extent.X + box.Extent.Y * box.Extent.Y + box.Extent.Z * box.Extent.Z);
}

// FUNCTION: BFME2 0x0019B5D0 size=95 name=?Get_Bounding_Box@HLodClass@@UBEABVAABoxClass@@XZ evidence=N:ledger tier=A
const AABoxClass &HLodClass::Get_Bounding_Box(void) const
{
	// With a bounding-box level the cached box is that box moved by the transform.
	if (BoundingBoxIndex >= 0) {
		AABoxClass box;
		Get_Obj_Space_Bounding_Box(box);
		Get_Transform().Transform_Center_Extent_AABox(box.Center, box.Extent, &CachedBoundingBox.Center, &CachedBoundingBox.Extent);
	} else if (!(Bits & BOUNDING_VOLUMES_VALID)) {
		Update_Cached_Bounding_Volumes();
	}
	return CachedBoundingBox;
}

// FUNCTION: BFME2 0x0019B630 size=102 name=?Set_Max_Screen_Size@HLodClass@@UAEXHM@Z evidence=N:ledger tier=A
void HLodClass::Set_Max_Screen_Size(int lod_index, float size)
{
	if (lod_index >= 0 && lod_index < LodCount) {
		Lod[lod_index].MaxScreenSize = size;
		// The level costs depend on the limit: rebuild them and step down if the level now lies past it.
		Recalculate_Static_LOD_Factors();
		int fitting = Calculate_Cost_Value_Arrays(1.0f, Value, Cost);
		if (CurLod < fitting) {
			Set_LOD_Level(fitting);
		}
	}
}

