// FUNCTION: BFME2 0x0019C180 size=176 name=?Intersect_OBBox@HLodClass@@UAE_NAAVOBBoxIntersectionTestClass@@@Z evidence=N:ledger tier=A
bool HLodClass::Intersect_AABox(AABoxIntersectionTestClass &boxtest)
{
	if (Are_Sub_Object_Transforms_Dirty()) {
		Update_Sub_Object_Transforms();
	}

	bool res = false;
	int i;

	// collide against the top LOD
	int top = LodCount - 1;
	for (i = 0; i < Lod[top].Count(); i++) {
		res |= Lod[top][i].Model->Intersect_AABox(boxtest);
	}

	for (i = 0; i < AdditionalModels.Count(); i++) {
		res |= AdditionalModels[i].Model->Intersect_AABox(boxtest);
	}

	return res;
}

// FUNCTION: BFME2 0x0019C230 size=445 name=?Free@HLodClass@@IAEXXZ evidence=N:ledger tier=A
void HLodClass::Free(void)
{
	// Detach and drop every level's models, then the levels themselves.
	for (int level = 0; level < LodCount; level++) {
		for (int node = 0; node < Lod[level].Count(); node++) {
			RenderObjClass *model = Lod[level][node].Model;
			Lod[level][node].Model = 0;
			model->Set_Container(0);
			model->Release_Ref();
		}
		Lod[level].Delete_All();
	}
	if (Lod != 0) {
		::delete [] Lod;
		Lod = 0;
	}
	LodCount = 0;

	if (Cost != 0) {
		delete [] Cost;
		Cost = 0;
	}
	if (Value != 0) {
		delete [] Value;
		Value = 0;
	}

	for (int extra = 0; extra < AdditionalModels.Count(); extra++) {
		RenderObjClass *model = AdditionalModels[extra].Model;
		AdditionalModels[extra].Model = 0;
		model->Set_Container(0);
		model->Release_Ref();
	}
	AdditionalModels.Delete_All();

	if (SnapPoints != 0) {
		SnapPoints->Release_Ref();
		SnapPoints = 0;
	}
	if (ProxyArray != 0) {
		ProxyArray->Release_Ref();
		ProxyArray = 0;
	}
}

// FUNCTION: BFME2 0x0019C3F0 size=294 name=?Get_Obj_Space_Bounding_Box@HLodClass@@UBEXAAVAABoxClass@@@Z evidence=N:ledger tier=A
void HLodClass::Get_Obj_Space_Bounding_Box(AABoxClass &box) const
{
	// Do we have a bounding box mesh?
	int count = Lod[LodCount - 1].Count();
	if (BoundingBoxIndex >= 0 && BoundingBoxIndex < count) {

		RenderObjClass *mesh = Lod[LodCount - 1][BoundingBoxIndex].Model;
		if (mesh != NULL && mesh->Class_ID() == CLASSID_OBBOX) {

			OBBoxRenderObjClass *obbox_mesh = (OBBoxRenderObjClass *)mesh;

			// Determine what the box's transform 'should' be this frame.
			// Note: We do this because some animation types don't update unless they are visible.
			Matrix3D box_tm;
			Simple_Evaluate_Bone(Lod[LodCount - 1][BoundingBoxIndex].BoneIndex, &box_tm);

			// Convert the OBBox from its coordinate system to the coordinate system of the HLOD.
			Matrix3D world_to_hlod_tm;
			Matrix3D box_to_hlod_tm;

			Get_Transform().Get_Orthogonal_Inverse(world_to_hlod_tm);
			Matrix3D::Multiply(world_to_hlod_tm, box_tm, &box_to_hlod_tm);

			box_to_hlod_tm.Transform_Center_Extent_AABox(obbox_mesh->Get_Local_Center(),
				obbox_mesh->Get_Local_Extent(), &box.Center, &box.Extent);
		}

	} else {
		Animatable3DObjClass::Get_Obj_Space_Bounding_Box(box);
	}
}

// FUNCTION: BFME2 0x0019C5B0 size=86 name=?Set_LOD_Bias@HLodClass@@UAEXM@Z evidence=N:ledger tier=A
void HLodClass::Set_LOD_Bias(float bias)
{
	if (!(bias > 0.0f)) {
		bias = 0.0f;
	}
	LODBias = bias;
	int count = AdditionalModels.Count();
	for (int index = 0; index < count; index++) {
		AdditionalModels[index].Model->Set_LOD_Bias(bias);
	}
}

