// FUNCTION: BFME2 0x0019C700 size=38 name=?Is_NULL_Lod_Included@HLodClass@@UBE_NXZ evidence=N:ledger tier=A
bool HLodClass::Is_NULL_Lod_Included(void) const
{
	// The null level is a single class-0x16 model at level 0.
	bool included = false;
	if (LodCount > 0) {
		RenderObjClass *first = Lod[0][0].Model;
		if (first != 0) {
			included = (first->Class_ID() == CLASSID_NULL);
		}
	}
	return included;
}

// FUNCTION: BFME2 0x0019C730 size=17 name=?Get_Proxy_Count@HLodClass@@UBEHXZ evidence=N:ledger tier=A
int HLodClass::Get_Proxy_Count(void) const
{
	if (ProxyArray != 0) {
		return ProxyArray->Length();
	}
	return 0;
}

// FUNCTION: BFME2 0x0019C750 size=305 name=?Get_Proxy@HLodClass@@UBE_NHAAVProxyClass@@@Z evidence=N:ledger tier=A
bool HLodClass::Get_Proxy(int index, ProxyClass &proxy) const
{
	bool retval = false;

	if (ProxyArray != NULL) {

		// Lookup the proxy's transform
		HTree->Base_Update(Get_Transform());
		BfmeProxyTransform transform(HTree->Peek_Pivot((*ProxyArray)[index].BoneIndex).Current);
		Set_Hierarchy_Valid(false);

		// Pass the data onto the proxy object
		proxy.Set_Transform(transform);
		proxy.Set_Name((*ProxyArray)[index].Name);
		retval = true;

	} else {
		proxy.Set_Name("");
		BfmeProxyTransform identity;
		identity.Make_Identity();
		proxy.Set_Transform(identity);
	}

	return retval;
}

// FUNCTION: BFME2 0x0019C890 size=185 name=?Get_Num_Polys@HLodClass@@UBEHXZ evidence=N:ledger tier=A
int HLodClass::Get_Num_Polys(void) const
{
	// Only visible models count: the current level's and the attached ones.
	int polys = 0;
	int shown = Lod[CurLod].Count();
	for (int node = 0; node < shown; node++) {
		if (Lod[CurLod][node].Model->Is_Not_Hidden_At_All()) {
			polys += Lod[CurLod][node].Model->Get_Num_Polys();
		}
	}
	int attached = AdditionalModels.Count();
	for (int extra = 0; extra < attached; extra++) {
		if (AdditionalModels[extra].Model->Is_Not_Hidden_At_All()) {
			polys += AdditionalModels[extra].Model->Get_Num_Polys();
		}
	}
	return polys;
}

// FUNCTION: BFME2 0x0019C950 size=293 name=?Render@HLodClass@@UAEXAAVRenderInfoClass@@@Z evidence=N:ledger tier=A
void HLodClass::Render(RenderInfoClass & rinfo)
{
	int i;

	if (Is_Not_Hidden_At_All() == false) {
		return;
	}

	Animatable3DObjClass::Render(rinfo);

	for (i = 0; i < Lod[CurLod].Count(); i++) {
		if (Lod[CurLod][i].Model->Class_ID() != CLASSID_OBBOX)	///We have no use for these - MW
			Lod[CurLod][i].Model->Render(rinfo);
	}

	if (Is_Sub_Objects_Match_LOD_Enabled()) {
		for (i = 0; i < AdditionalModels.Count(); i++) {
			AdditionalModels[i].Model->Set_LOD_Level(Get_LOD_Level());
			AdditionalModels[i].Model->Render(rinfo);
		}
	} else {
		for (i = 0; i < AdditionalModels.Count(); i++) {
			AdditionalModels[i].Model->Render(rinfo);
		}
	}
}

// FUNCTION: BFME2 0x0019CA80 size=126 name=?Notify_Added@HLodClass@@UAEXPAVSceneClass@@@Z evidence=N:ledger tier=A
void HLodClass::Notify_Added(SceneClass *scene)
{
	RenderObjClass::Notify_Added(scene);

	int shown = Lod[CurLod].Count();
	for (int node = 0; node < shown; node++) {
		Lod[CurLod][node].Model->Notify_Added(scene);
	}
	int attached = AdditionalModels.Count();
	for (int extra = 0; extra < attached; extra++) {
		AdditionalModels[extra].Model->Notify_Added(scene);
	}
}

// FUNCTION: BFME2 0x0019CB00 size=134 name=?Notify_Removed@HLodClass@@UAEXPAVSceneClass@@@Z evidence=N:ledger tier=A
void HLodClass::Notify_Removed(SceneClass *scene)
{
	int shown = Lod[CurLod].Count();
	for (int node = 0; node < shown; node++) {
		Lod[CurLod][node].Model->Notify_Removed(scene);
	}
	int attached = AdditionalModels.Count();
	for (int extra = 0; extra < attached; extra++) {
		AdditionalModels[extra].Model->Notify_Removed(scene);
	}

	RenderObjClass::Notify_Removed(scene);
}

// FUNCTION: BFME2 0x0019CB90 size=16 name=?Get_Num_Sub_Objects@HLodClass@@UBEHXZ evidence=N:ledger tier=A
int HLodClass::Get_Num_Sub_Objects(void) const
{
	return _bfme_ro_v28() + AdditionalModels.Count();
}

// FUNCTION: BFME2 0x0019CBA0 size=32 name=?_bfme_ro_v28@HLodClass@@UBEHXZ evidence=N:ledger tier=A
int HLodClass::_bfme_ro_v28(void) const
{
	int total = 0;
	for (int level = 0; level < LodCount; level++) {
		total += Lod[level].Count();
	}
	return total;
}

// FUNCTION: BFME2 0x0019CBC0 size=133 name=?Get_Sub_Object@HLodClass@@UBEPAVRenderObjClass@@H@Z evidence=N:ledger tier=A
RenderObjClass *HLodClass::Get_Sub_Object(int index) const
{
	// The index runs through every level in turn, then through the attached models.
	for (int level = 0; level < LodCount; level++) {
		if (index < Lod[level].Count()) {
			Lod[level][index].Model->Add_Ref();
			return Lod[level][index].Model;
		}
		index -= Lod[level].Count();
	}
	AdditionalModels[index].Model->Add_Ref();
	return AdditionalModels[index].Model;
}

// FUNCTION: BFME2 0x0019CC50 size=115 name=?Get_Num_Sub_Objects_On_Bone@HLodClass@@UBEHH@Z evidence=N:ledger tier=A
int HLodClass::Get_Num_Sub_Objects_On_Bone(int boneindex) const
{
	int found = 0;
	for (int level = 0; level < LodCount; level++) {
		for (int node = 0; node < Lod[level].Count(); node++) {
			if (Lod[level][node].BoneIndex == boneindex) {
				found++;
			}
		}
	}
	for (int extra = 0; extra < AdditionalModels.Count(); extra++) {
		if (AdditionalModels[extra].BoneIndex == boneindex) {
			found++;
		}
	}
	return found;
}

// FUNCTION: BFME2 0x0019CCD0 size=256 name=?Get_Sub_Object_On_Bone@HLodClass@@UBEPAVRenderObjClass@@HH@Z evidence=N:ledger tier=A
RenderObjClass *HLodClass::Get_Sub_Object_On_Bone(int index, int boneindex) const
{
	int seen = 0;
	for (int level = 0; level < LodCount; level++) {
		for (int node = 0; node < Lod[level].Count(); node++) {
			if (Lod[level][node].BoneIndex == boneindex) {
				if (seen == index) {
					Lod[level][node].Model->Add_Ref();
					return Lod[level][node].Model;
				}
				seen++;
			}
		}
	}
	for (int extra = 0; extra < AdditionalModels.Count(); extra++) {
		if (AdditionalModels[extra].BoneIndex == boneindex) {
			if (seen == index) {
				AdditionalModels[extra].Model->Add_Ref();
				return AdditionalModels[extra].Model;
			}
			seen++;
		}
	}
	return 0;
}

// FUNCTION: BFME2 0x0019CDD0 size=176 name=?Get_Sub_Object_Bone_Index@HLodClass@@UBEHPAVRenderObjClass@@@Z evidence=N:ledger tier=A
int HLodClass::Get_Sub_Object_Bone_Index(RenderObjClass *subobj) const
{
	for (int level = 0; level < LodCount; level++) {
		for (int node = 0; node < Lod[level].Count(); node++) {
			if (Lod[level][node].Model == subobj) {
				return Lod[level][node].BoneIndex;
			}
		}
	}
	for (int extra = 0; extra < AdditionalModels.Count(); extra++) {
		if (AdditionalModels[extra].Model == subobj) {
			return AdditionalModels[extra].BoneIndex;
		}
	}
	return 0;
}

// FUNCTION: BFME2 0x0019CE80 size=31 name=?Get_Sub_Object_Bone_Index@HLodClass@@UBEHHH@Z evidence=N:ledger tier=A
int HLodClass::Get_Sub_Object_Bone_Index(int lod_index, int model_index) const
{
	return Lod[lod_index][model_index].BoneIndex;
}

// FUNCTION: BFME2 0x0019CEA0 size=168 name=?Removed_Added_Sub_Objects_From_Bones@HLodClass@@UAEXXZ evidence=N:ledger tier=A
void HLodClass::Removed_Added_Sub_Objects_From_Bones(void)
{
	if (AdditionalModels.Count() != 0) {
		for (int extra = 0; extra < AdditionalModels.Count(); extra++) {
			RenderObjClass *model = AdditionalModels[extra].Model;
			AdditionalModels[extra].Model = 0;
			model->Set_Container(0);
			if (Is_In_Scene()) {
				model->Notify_Removed(Scene);
			}
			model->Release_Ref();
		}
		AdditionalModels.Delete_All();
		Update_Sub_Object_Bits();
		Update_Obj_Space_Bounding_Volumes();
	}
}

// FUNCTION: BFME2 0x0019CF50 size=324 name=?Cast_Ray@HLodClass@@UAE_NAAVRayCollisionTestClass@@@Z evidence=N:ledger tier=A
bool HLodClass::Cast_Ray(RayCollisionTestClass &raytest)
{
	if (Are_Sub_Object_Transforms_Dirty()) {
		Update_Sub_Object_Transforms();
	}

	bool res = false;
	int i;

	// collide against the top LOD
	int top = LodCount - 1;

	// A stop-at-first-hit cast goes to the bounding box object alone when the level has one.
	if (raytest.StopAtFirstHit) {
		for (i = 0; i < Lod[top].Count(); i++) {
			RenderObjClass *model = Lod[top][i].Model;
			if (model->Class_ID() == CLASSID_OBBOX) {
				return model->Cast_Ray(raytest);
			}
		}
	}

	for (i = 0; i < Lod[top].Count(); i++) {
		res |= Lod[top][i].Model->Cast_Ray(raytest);
		if (res && raytest.StopAtFirstHit) {
			return true;
		}
	}

	for (i = 0; i < AdditionalModels.Count(); i++) {
		res |= AdditionalModels[i].Model->Cast_Ray(raytest);
		if (res && raytest.StopAtFirstHit) {
			return true;
		}
	}

	return res;
}

// FUNCTION: BFME2 0x0019D0A0 size=166 name=?Prepare_LOD@HLodClass@@UAEXAAVCameraClass@@@Z evidence=N:ledger tier=A
void HLodClass::Prepare_LOD(CameraClass &camera)
{
	if (Is_Not_Hidden_At_All()) {
		float screen = Get_Screen_Size(camera);
		if (LodCount > 1) {
			int fitting = Calculate_Cost_Value_Arrays(screen, Value, Cost);
			if (CurLod < fitting) {
				Set_LOD_Level(fitting);
			}
		}
		int attached = AdditionalModels.Count();
		for (int extra = 0; extra < attached; extra++) {
			if (AdditionalModels[extra].Model->Is_Not_Hidden_At_All()) {
				AdditionalModels[extra].Model->Prepare_LOD(camera);
			}
		}
	}
}

// FUNCTION: BFME2 0x0019D150 size=251 name=?Recalculate_Static_LOD_Factors@HLodClass@@UAEXXZ evidence=N:ledger tier=A
void HLodClass::Recalculate_Static_LOD_Factors(void)
{
	// A level's fixed cost is its visible polygon count; its benefit grows towards 1 with the count.
	for (int level = 0; level < LodCount; level++) {
		Lod[level].PixelCostPerArea = 0.0f;

		int polys = 0;
		int count = Lod[level].Count();
		for (int node = 0; node < count; node++) {
			if (Lod[level][node].Model->Is_Not_Hidden_At_All()) {
				polys += Lod[level][node].Model->Get_Num_Polys();
			}
		}

		Lod[level].NonPixelCost = (polys != 0) ? (float)polys : 0.000001f;
		Lod[level].BenefitFactor = (polys != 0) ? 1.0f - 0.5f / (float)(polys * polys) : 0.0f;
	}
}

// FUNCTION: BFME2 0x0019D250 size=203 name=?Increment_LOD@HLodClass@@UAEXXZ evidence=N:ledger tier=A
void HLodClass::Increment_LOD(void)
{
	if (CurLod >= LodCount - 1) {
		return;
	}
	if (Is_In_Scene()) {
		int leaving = Lod[CurLod].Count();
		for (int node = 0; node < leaving; node++) {
			Lod[CurLod][node].Model->Notify_Removed(Scene);
		}
	}
	CurLod++;
	if (Is_In_Scene()) {
		int arriving = Lod[CurLod].Count();
		for (int node = 0; node < arriving; node++) {
			Lod[CurLod][node].Model->Notify_Added(Scene);
		}
	}
}

// FUNCTION: BFME2 0x0019D320 size=203 name=?Decrement_LOD@HLodClass@@UAEXXZ evidence=N:ledger tier=A
void HLodClass::Decrement_LOD(void)
{
	if (CurLod < 1) {
		return;
	}
	if (Is_In_Scene()) {
		int leaving = Lod[CurLod].Count();
		for (int node = 0; node < leaving; node++) {
			Lod[CurLod][node].Model->Notify_Removed(Scene);
		}
	}
	CurLod--;
	if (Is_In_Scene()) {
		int arriving = Lod[CurLod].Count();
		for (int node = 0; node < arriving; node++) {
			Lod[CurLod][node].Model->Notify_Added(Scene);
		}
	}
}

// FUNCTION: BFME2 0x0019D3F0 size=238 name=?Set_LOD_Level@HLodClass@@UAEXH@Z evidence=N:ledger tier=A
void HLodClass::Set_LOD_Level(int lod)
{
	lod = (lod < 0) ? 0 : lod;
	lod = (lod < LodCount - 1) ? lod : LodCount - 1;
	if (lod == CurLod) {
		return;
	}

	// Swap the level's models in the scene.
	if (Is_In_Scene()) {
		int leaving = Lod[CurLod].Count();
		for (int node = 0; node < leaving; node++) {
			Lod[CurLod][node].Model->Notify_Removed(Scene);
		}
	}
	CurLod = lod;
	if (Is_In_Scene()) {
		int arriving = Lod[CurLod].Count();
		for (int node = 0; node < arriving; node++) {
			Lod[CurLod][node].Model->Notify_Added(Scene);
		}
	}
}

// FUNCTION: BFME2 0x0019D4E0 size=227 name=?Scale@HLodClass@@UAEXM@Z evidence=N:ledger tier=A
void HLodClass::Scale(float scale)
{
	if (scale == 1.0f) {
		return;
	}

	for (int level = 0; level < LodCount; level++) {
		for (int node = 0; node < Lod[level].Count(); node++) {
			Lod[level][node].Model->Scale(scale);
		}
	}
	for (int extra = 0; extra < AdditionalModels.Count(); extra++) {
		AdditionalModels[extra].Model->Scale(scale);
	}

	// The skeleton scales with the models; the container recomputes its bounds.
	HTree->Scale(scale);
	IsTreeValid = false;
	if (Container != 0) {
		Container->Update_Obj_Space_Bounding_Volumes();
	}
}

// FUNCTION: BFME2 0x0019D5D0 size=17 name=?Get_Num_Snap_Points@HLodClass@@UAEHXZ evidence=N:ledger tier=A
int HLodClass::Get_Num_Snap_Points(void)
{
	if (SnapPoints != 0) {
		return SnapPoints->Count();
	}
	return 0;
}

// FUNCTION: BFME2 0x0019D5F0 size=71 name=?Get_Snap_Point@HLodClass@@UAEXHPAVVector3@@@Z evidence=N:ledger tier=A
void HLodClass::Get_Snap_Point(int index, Vector3 *set)
{
	if (SnapPoints != 0) {
		*set = (*SnapPoints)[index];
	} else {
		set->X = set->Y = set->Z = 0.0f;
	}
}

